	*len -= vnet_hdr_sz;

	if (!copy_from_iter_full(vnet_hdr, sizeof(*vnet_hdr), &msg->msg_iter))
		return -EFAULT;

	ret = __packet_snd_vnet_parse(vnet_hdr, *len);
